#!/bin/bash
set -e

# Move any existing local manifests aside instead of deleting them.
if [ -d .repo/local_manifests ]; then
  mv .repo/local_manifests ".repo/local_manifests.bak.$(date +%s)"
fi

repo init -u https://github.com/Evolution-X/manifest -b cnb --git-lfs --depth 1 --no-verify
git clone https://github.com/protpr0t/local_manifest_alphaplus -b evox-17 .repo/local_manifests
/opt/crave/resync.sh

# Unofficial builds need signing keys generated by the Evolution X keys template.
# keys.sh only exists in a fresh template clone, so if it is missing the directory
# is either absent or holds something else (for example a leftover repo that
# does not contain valid keys.mk). Move that aside and generate fresh keys.
KEYS_DIR=vendor/evolution-priv/keys
if [ ! -f "$KEYS_DIR/keys.sh" ]; then
  if [ -d "$KEYS_DIR" ]; then
    mv "$KEYS_DIR" "$KEYS_DIR.bak.$(date +%s)"
  fi
  git clone https://github.com/Evolution-X/vendor_evolution-priv_keys-template "$KEYS_DIR"
  (cd "$KEYS_DIR" && ./keys.sh)
fi

# Evolution X build type values are "Official" and "Unofficial" (case-sensitive).
export EVO_BUILD_TYPE=Unofficial

. build/envsetup.sh
lunch lineage_alphaplus-cp2a-eng
m installclean
m evolution
